import json,subprocess
def load(path):
    p=subprocess.run(['ansible-inventory','-i',str(path),'--list'],capture_output=True,text=True,timeout=10)
    if p.returncode:raise ValueError('inventory failed')
    try:return json.loads(p.stdout)
    except ValueError as e:raise ValueError('invalid inventory output') from e
def hosts(data,group):
    if group not in data or group=='_meta':raise ValueError('group is missing')
    result=set();active=set()
    def visit(name):
        if name in active:raise ValueError('cyclic group graph')
        active.add(name);node=data.get(name,{})
        result.update(node.get('hosts',[]))
        for child in node.get('children',[]):visit(child)
        active.remove(name)
    visit(group)
    return sorted(result)
def execute(path,group,expected_environment,limit):
    if not isinstance(group,str) or not group or type(limit) is not int or limit<1 or not isinstance(expected_environment,str) or not expected_environment.strip():raise ValueError('invalid scope')
    data=load(path);selected=hosts(data,group)
    if not selected or len(selected)>limit:raise ValueError('empty or oversized deployment scope')
    values=data.get('_meta',{}).get('hostvars',{});result=[]
    for name in selected:
        value=values.get(name,{})
        if value.get('environment')!=expected_environment:raise ValueError('environment mismatch')
        address=value.get('ansible_host')
        if not isinstance(address,str) or not address.strip():raise ValueError('explicit address required')
        result.append({'alias':name,'address':address,'environment':value['environment']})
    return {'group':group,'targets':result,'count':len(result)}
