import json,subprocess
def load(path):
    p=subprocess.run(['ansible-inventory','-i',str(path),'--list'],capture_output=True,text=True,timeout=10)
    if p.returncode:raise ValueError('inventory failed')
    try:return json.loads(p.stdout)
    except ValueError as e:raise ValueError('invalid inventory output') from e
def hosts(data,group):
    if group not in data or group=='_meta':raise ValueError('group is missing')
    result=set();active=set()
    def visit(name):
        if name in active:raise ValueError('cyclic group graph')
        active.add(name);node=data.get(name,{})
        result.update(node.get('hosts',[]))
        for child in node.get('children',[]):visit(child)
        active.remove(name)
    visit(group)
    return sorted(result)
def execute(path,group):
    data=load(path);selected=hosts(data,group)
    if not selected:raise ValueError('empty scope')
    values=data.get('_meta',{}).get('hostvars',{});owners={};result=[]
    for alias in selected:
        value=values.get(alias,{})
        device=value.get('physical_device_id');canonical=value.get('canonical_alias')
        if not isinstance(device,str) or not device.strip() or not isinstance(canonical,str) or not canonical.strip():raise ValueError('explicit device ownership required')
        owners.setdefault(device,[]).append((alias,value,canonical))
    for device,rows in sorted(owners.items()):
        canonical_set={r[2] for r in rows}
        if len(canonical_set)!=1:raise ValueError('conflicting canonical aliases')
        canonical=next(iter(canonical_set));names={r[0] for r in rows}
        if canonical not in names:raise ValueError('canonical alias outside selected scope')
        endpoints={(v.get('ansible_host'),v.get('ansible_port',22)) for _,v,_ in rows}
        if len(endpoints)!=1:raise ValueError('device connection disagreement')
        address,port=next(iter(endpoints))
        if not isinstance(address,str) or not address or type(port) is not int or not 1<=port<=65535:raise ValueError('invalid endpoint')
        result.append({'device':device,'canonical':canonical,'aliases':sorted(names),'address':address,'port':port})
    return result
